// launcher/launcher.js
// Learning Arcade: the edu-games library launcher.
//
// Plain ES2022 module, no dependencies, no build step. Every URL is relative so the
// launcher works from any static host at any base path.
//
// Data sources (all optional at runtime; the UI degrades gracefully):
//   games/index.json        generated by tools/build-index.mjs   (override with ?index=<url>)
//   curriculum/map.json     subject names/colours + skill names  (fallback table below)
//   ../kit/learn/progress.js player level/XP + per-game stats     (dynamic import, hidden if missing)
//
// Test hook: window.__eduLauncher = { state, openGame, closeModal, refresh }.

export const LIBRARY_TITLE = 'Learning Arcade';

const DEFAULT_INDEX_URL = 'games/index.json';
const CURRICULUM_URL = 'curriculum/map.json';
const PROGRESS_MODULE = '../kit/learn/progress.js'; // relative to this module
const RECENT_LIMIT = 4;
const PLATFORM_SOURCE = 'edu-games';

// Fallback subject table (ARCHITECTURE.md section 7). curriculum/map.json overrides name/colour.
const SUBJECTS = [
  { id: 'math', name: 'Mathematics', short: 'Math', color: '#4F7CFF' },
  { id: 'science', name: 'Science', short: 'Science', color: '#22C55E' },
  { id: 'ela', name: 'English Language Arts', short: 'ELA', color: '#F59E0B' },
  { id: 'social', name: 'Social Studies', short: 'Social Studies', color: '#EF4444' },
  { id: 'cs', name: 'Computer Science and Digital Literacy', short: 'Computer Science', color: '#8B5CF6' },
  { id: 'languages', name: 'World Languages', short: 'Languages', color: '#EC4899' },
  { id: 'arts', name: 'Arts and Music', short: 'Arts & Music', color: '#14B8A6' },
];
const UNKNOWN_SUBJECT_COLOR = '#64748B';
const BANDS = [
  { id: 'early', label: 'Early', grades: '1-2', min: 1, max: 2 },
  { id: 'elementary', label: 'Elementary', grades: '3-5', min: 3, max: 5 },
  { id: 'middle', label: 'Middle', grades: '6-8', min: 6, max: 8 },
  { id: 'high', label: 'High', grades: '9-12', min: 9, max: 12 },
];
const SORTS = [
  ['recommended', 'Recommended'],
  ['newest', 'Newest'],
  ['best', 'Best score'],
  ['az', 'A-Z'],
];

const state = {
  games: [],
  indexMeta: null,
  indexError: null,
  indexUrl: DEFAULT_INDEX_URL,
  subjects: new Map(SUBJECTS.map(s => [s.id, { ...s }])),
  skillNames: new Map(),
  progress: null,          // Progress module object or null
  progressMod: null,       // the module namespace (for optional helpers such as totalXPForLevel)
  stats: new Map(),        // gameId -> { plays, bestScore, totalXP, lastPlayed } from Progress
  live: new Map(),         // gameId -> same shape, accumulated from platform events this session
  livePlayer: null,        // { level, xp, xpToNext } from 'xp'/'levelup' events
  filters: { subjects: new Set(), bands: new Set(), grade: '', mechanic: '', q: '', sort: 'recommended' },
  modal: null,             // { game, frame, opener, focusables }
  seed: null,              // ?seed= on the launcher URL is forwarded to every game
};

// ----------------------------------------------------------------------------
// Small helpers
// ----------------------------------------------------------------------------
const $ = (sel, root = document) => root.querySelector(sel);
const isFn = f => typeof f === 'function';
const num = v => (typeof v === 'number' && Number.isFinite(v)) ? v : (typeof v === 'string' && v.trim() !== '' && Number.isFinite(+v)) ? +v : null;
const clamp01 = v => Math.min(1, Math.max(0, v));
const fmt = n => (Math.round(num(n) ?? 0)).toLocaleString();
const plural = (n, one, many = one + 's') => `${fmt(n)} ${n === 1 ? one : many}`;
const titleCase = s => String(s || '').replace(/[-_]+/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const humanize = s => { const t = titleCase(s); return t.charAt(0) + t.slice(1).toLowerCase(); };

function h(tag, attrs = {}, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v === undefined || v === null || v === false) continue;
    if (k === 'class') el.className = v;
    else if (k === 'style' && typeof v === 'object') for (const [p, val] of Object.entries(v)) el.style.setProperty(p, val);
    else if (k.startsWith('on') && isFn(v)) el.addEventListener(k.slice(2), v);
    else if (k === 'dataset') Object.assign(el.dataset, v);
    else if (v === true) el.setAttribute(k, '');
    else el.setAttribute(k, String(v));
  }
  for (const c of children.flat(Infinity)) {
    if (c === null || c === undefined || c === false) continue;
    el.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return el;
}

// Inline icons (author-controlled static markup).
const ICONS = {
  play: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.5.87l11-6.5a1 1 0 0 0 0-1.74l-11-6.5A1 1 0 0 0 8 5.5z"/></svg>',
  check: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7"/></svg>',
  clock: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
  external: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 4h6v6M20 4l-9 9M19 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h5"/></svg>',
  close: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
  empty: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="6" width="20" height="12" rx="4"/><path d="M7 10v4M5 12h4M15 11h.01M18 13h.01"/></svg>',
  search: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5M8 11h6"/></svg>',
};
function icon(name, cls = 'la-icon') {
  const span = h('span', { class: cls, 'aria-hidden': 'true' });
  span.innerHTML = ICONS[name] || '';
  return span;
}

function subjectOf(id) {
  if (!state.subjects.has(id)) {
    state.subjects.set(id, { id, name: titleCase(id), short: titleCase(id), color: UNKNOWN_SUBJECT_COLOR });
  }
  return state.subjects.get(id);
}
const bandOf = id => BANDS.find(b => b.id === id) || null;
const bandForGrades = ([lo, hi]) => (BANDS.find(b => lo <= b.max && hi >= b.min) || BANDS[1]).id;
const gradeLabel = g => g.grades[0] === g.grades[1] ? `Grade ${g.grades[0]}` : `Grades ${g.grades[0]}-${g.grades[1]}`;
const compareVersion = (a, b) => {
  const pa = String(a || '0').split('.').map(x => parseInt(x, 10) || 0);
  const pb = String(b || '0').split('.').map(x => parseInt(x, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) { const d = (pa[i] || 0) - (pb[i] || 0); if (d) return d; }
  return 0;
};

function gameUrl(game) {
  let url = game.path + 'index.html';
  if (state.seed) url += '?seed=' + encodeURIComponent(state.seed);
  return url;
}
const thumbUrl = game => game.thumbnail ? game.path + game.thumbnail : null;

// ----------------------------------------------------------------------------
// Data loading
// ----------------------------------------------------------------------------
function resolveIndexUrl() {
  try {
    const q = new URL(location.href).searchParams;
    state.seed = q.get('seed') || null;
    const custom = q.get('index');
    if (custom) return custom;
  } catch { /* ignore */ }
  return DEFAULT_INDEX_URL;
}

async function loadIndex() {
  state.indexUrl = resolveIndexUrl();
  try {
    const res = await fetch(state.indexUrl, { cache: 'no-cache' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    if (!data || !Array.isArray(data.games)) throw new Error('index has no "games" array');
    state.indexError = null;
    return data;
  } catch (e) {
    state.indexError = (e && e.message) || String(e);
    return null;
  }
}

async function loadCurriculum() {
  try {
    const res = await fetch(CURRICULUM_URL, { cache: 'no-cache' });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

function applyCurriculum(map) {
  if (!map || !Array.isArray(map.subjects)) return;
  for (const s of map.subjects) {
    if (!s || !s.id) continue;
    const cur = state.subjects.get(s.id) || { id: s.id, short: titleCase(s.id) };
    const name = typeof s.name === 'string' && s.name.trim() ? s.name.trim() : cur.name || titleCase(s.id);
    cur.name = name;
    if (!SUBJECTS.some(x => x.id === s.id)) cur.short = name.replace(/\s*\(.*$/, '');
    if (typeof s.color === 'string' && /^#[0-9a-f]{3,8}$/i.test(s.color)) cur.color = s.color;
    if (!cur.color) cur.color = UNKNOWN_SUBJECT_COLOR;
    state.subjects.set(s.id, cur);
    for (const g of Object.values(s.grades || {})) {
      for (const t of (g && g.topics) || []) {
        for (const k of (t && t.skills) || []) if (k && k.id && k.name) state.skillNames.set(k.id, k.name);
      }
    }
  }
}

// The kit may be absent or under construction: never let its failure break the launcher.
// Progress reads storage on every call, so one import stays current while games run in the iframe.
async function loadProgress() {
  try {
    const mod = await import(PROGRESS_MODULE);
    const P = (mod && (mod.Progress || mod.default)) || mod;
    if (!P || !isFn(P.gameStats)) return null;
    state.progressMod = mod;
    return P;
  } catch {
    return null;
  }
}

function normaliseGame(raw, i) {
  const g = { ...raw };
  g.id = String(g.id || `game-${i + 1}`);
  g.title = String(g.title || titleCase(g.id));
  g.tagline = typeof g.tagline === 'string' ? g.tagline : '';
  g.description = typeof g.description === 'string' ? g.description : '';
  g.subject = typeof g.subject === 'string' && g.subject ? g.subject : 'math';
  subjectOf(g.subject);
  let grades = Array.isArray(g.grades) ? g.grades.map(num).filter(v => v !== null) : [];
  if (!grades.length) { const b = bandOf(g.gradeBand); grades = b ? [b.min, b.max] : [1, 12]; }
  g.grades = [Math.max(1, Math.min(...grades)), Math.min(12, Math.max(...grades))];
  g.gradeBand = bandOf(g.gradeBand) ? g.gradeBand : bandForGrades(g.grades);
  g.skills = Array.isArray(g.skills) ? g.skills.filter(s => typeof s === 'string') : [];
  g.topics = Array.isArray(g.topics) ? g.topics.filter(s => typeof s === 'string') : [];
  g.genre = Array.isArray(g.genre) ? g.genre.filter(s => typeof s === 'string') : [];
  g.mechanic = typeof g.mechanic === 'string' && g.mechanic ? g.mechanic : 'unknown';
  g.duration = typeof g.duration === 'string' ? g.duration : '';
  g.status = typeof g.status === 'string' ? g.status : '';
  let p = typeof g.path === 'string' && g.path ? g.path : `games/${g.id}/`;
  if (!p.endsWith('/')) p += '/';
  g.path = p;
  g.thumbnail = typeof g.thumbnail === 'string' && g.thumbnail ? g.thumbnail : 'thumb.svg';
  g._order = i;
  g._added = Date.parse(g.added || g.createdAt || g.releaseDate || g.date || '') || 0;
  const subj = subjectOf(g.subject);
  g._hay = [
    g.title, g.tagline, g.description, g.id,
    ...g.skills, ...g.skills.map(s => state.skillNames.get(s) || ''),
    ...g.topics, ...g.genre, humanize(g.mechanic), subj.name, subj.short, g.gradeBand,
  ].join(' ').toLowerCase();
  return g;
}

function setGames(index) {
  state.indexMeta = index;
  state.games = index ? index.games.map(normaliseGame) : [];
}

// ----------------------------------------------------------------------------
// Progress adapter (per-game stats and player level), tolerant of a stale or
// missing kit. Stats from Progress are merged with values learned from
// platform events this session ("live"), taking the max of each counter.
// ----------------------------------------------------------------------------
const emptyStats = () => ({ plays: 0, bestScore: 0, totalXP: 0, lastPlayed: 0 });
function normStats(s) {
  if (!s || typeof s !== 'object') return emptyStats();
  let last = s.lastPlayed;
  if (typeof last === 'string') last = Date.parse(last) || 0;
  if (last instanceof Date) last = last.getTime();
  return { plays: num(s.plays) ?? 0, bestScore: num(s.bestScore) ?? 0, totalXP: num(s.totalXP) ?? 0, lastPlayed: num(last) ?? 0 };
}

function refreshStats() {
  const map = new Map();
  const P = state.progress;
  if (P) {
    try {
      const all = isFn(P.allGameStats) ? P.allGameStats() : null;
      const entries = Array.isArray(all) ? all.map(s => [s && (s.gameId || s.id), s]) : Object.entries(all || {});
      for (const [id, s] of entries) if (id && s) map.set(String(id), normStats(s));
    } catch { /* ignore */ }
    for (const g of state.games) {
      if (map.has(g.id)) continue;
      try { map.set(g.id, normStats(P.gameStats(g.id))); } catch { /* ignore */ }
    }
  }
  state.stats = map;
}

function statsFor(id) {
  const a = state.stats.get(id), b = state.live.get(id);
  if (!a && !b) return emptyStats();
  if (!a) return b;
  if (!b) return a;
  return {
    plays: Math.max(a.plays, b.plays),
    bestScore: Math.max(a.bestScore, b.bestScore),
    totalXP: Math.max(a.totalXP, b.totalXP),
    lastPlayed: Math.max(a.lastPlayed, b.lastPlayed),
  };
}
const hasStats = () => !!state.progress || state.live.size > 0;

function noteEnd(gameId, detail) {
  if (!gameId) return;
  const prev = state.live.get(gameId) || normStats(state.stats.get(gameId));
  const score = Math.max(num(detail.score) ?? 0, num(detail.bestScore) ?? 0);
  state.live.set(gameId, {
    plays: prev.plays + 1,
    bestScore: Math.max(prev.bestScore, score),
    totalXP: prev.totalXP + (num(detail.xpEarned) ?? 0),
    lastPlayed: Date.now(),
  });
}

function notePlayer(detail) {
  const level = num(detail.level), xp = num(detail.xp), xpToNext = num(detail.xpToNext);
  if (level === null && xp === null) return;
  state.livePlayer = { ...(state.livePlayer || {}), ...(level !== null && { level }), ...(xp !== null && { xp }), ...(xpToNext !== null && { xpToNext }) };
}

// Total XP needed to reach a level, when the kit exposes its curve (Progress.totalXPForLevel).
function levelCurve() {
  const P = state.progress, mod = state.progressMod;
  const f = (P && isFn(P.totalXPForLevel) && P.totalXPForLevel) || (mod && isFn(mod.totalXPForLevel) && mod.totalXPForLevel) || (P && isFn(P.xpForLevel) && P.xpForLevel) || null;
  return f ? (L => { try { return num(f(L)); } catch { return null; } }) : null;
}

function playerInfo() {
  const P = state.progress;
  if (!P && !state.livePlayer) return null;
  const p = { level: 1, xp: 0, xpToNext: null, pct: null, plays: 0 };
  if (P) {
    try {
      if (isFn(P.levelInfo)) {
        const li = P.levelInfo() || {};
        p.level = num(li.level) ?? 1;
        p.xp = num(li.xp) ?? 0;
        p.xpToNext = num(li.xpToNext);
        p.pct = num(li.levelProgress) !== null ? clamp01(li.levelProgress) : null;
      } else {
        p.level = num(P.level()) ?? 1;
        p.xp = num(P.xp()) ?? 0;
      }
    } catch { /* ignore */ }
    try { if (p.pct === null && isFn(P.levelProgress)) p.pct = clamp01(num(P.levelProgress()) ?? 0); } catch { /* ignore */ }
    try { if (p.xpToNext === null && isFn(P.xpToNext)) p.xpToNext = num(P.xpToNext()); } catch { /* ignore */ }
  }
  // Values learned from platform events win only when they are strictly ahead of what Progress reports
  // (e.g. a cross-origin game whose storage this window cannot read).
  const lp = state.livePlayer;
  if (lp) {
    const level = lp.level ?? p.level, xp = lp.xp ?? p.xp;
    if (level >= p.level && xp >= p.xp && (level !== p.level || xp !== p.xp)) {
      p.level = level; p.xp = xp; p.xpToNext = lp.xpToNext ?? null; p.pct = null;
    }
  }
  if (p.pct === null || p.xpToNext === null) {
    const curve = levelCurve();
    const lo = curve ? curve(p.level) : null, hi = curve ? curve(p.level + 1) : null;
    if (lo !== null && hi !== null && hi > lo) {
      if (p.pct === null) p.pct = clamp01((p.xp - lo) / (hi - lo));
      if (p.xpToNext === null) p.xpToNext = Math.max(0, hi - p.xp);
    }
  }
  for (const g of state.games) p.plays += statsFor(g.id).plays;
  return p;
}

// ----------------------------------------------------------------------------
// Filtering and sorting
// ----------------------------------------------------------------------------
const byTitle = (a, b) => a.title.localeCompare(b.title, undefined, { sensitivity: 'base' });

function recommendScore(g, ctx) {
  const s = statsFor(g.id);
  let score = 0;
  if (g.status === 'flagship') score += 2;
  if (!s.plays) score += 1.5;                           // something new to try
  if (ctx.recentSubjects.has(g.subject)) score += 1.25;  // subjects the player comes back to
  if (ctx.recentBands.has(g.gradeBand)) score += 1;      // same grade band as recent play
  if (s.plays > 0 && s.plays < 3) score += 0.5;          // started but not yet settled
  return score;
}

function recentGames() {
  return state.games
    .map(g => ({ g, s: statsFor(g.id) }))
    .filter(x => x.s.lastPlayed > 0 || x.s.plays > 0)
    .sort((a, b) => b.s.lastPlayed - a.s.lastPlayed || b.s.plays - a.s.plays)
    .map(x => x.g);
}

function visibleGames() {
  const f = state.filters;
  const tokens = f.q.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const grade = f.grade ? Number(f.grade) : 0;
  const list = state.games.filter(g =>
    (!f.subjects.size || f.subjects.has(g.subject)) &&
    (!f.bands.size || f.bands.has(g.gradeBand)) &&
    (!grade || (g.grades[0] <= grade && grade <= g.grades[1])) &&
    (!f.mechanic || g.mechanic === f.mechanic) &&
    tokens.every(t => g._hay.includes(t)));

  switch (f.sort) {
    case 'az': return list.sort(byTitle);
    case 'best': return list.sort((a, b) => statsFor(b.id).bestScore - statsFor(a.id).bestScore || statsFor(b.id).plays - statsFor(a.id).plays || byTitle(a, b));
    case 'newest': return list.sort((a, b) => b._added - a._added || compareVersion(b.version, a.version) || b._order - a._order);
    default: {
      const recent = recentGames().slice(0, 8);
      const ctx = { recentSubjects: new Set(recent.map(g => g.subject)), recentBands: new Set(recent.map(g => g.gradeBand)) };
      const score = new Map(list.map(g => [g.id, recommendScore(g, ctx)]));
      return list.sort((a, b) => score.get(b.id) - score.get(a.id) || a._order - b._order);
    }
  }
}

const filtersActive = () => {
  const f = state.filters;
  return !!(f.subjects.size || f.bands.size || f.grade || f.mechanic || f.q.trim());
};

function clearFilters() {
  const f = state.filters;
  f.subjects.clear(); f.bands.clear(); f.grade = ''; f.mechanic = ''; f.q = '';
  $('#search').value = '';
  $('#grade').value = '';
  $('#mechanic').value = '';
  renderFilters();
  renderGrid();
}

// ----------------------------------------------------------------------------
// Rendering
// ----------------------------------------------------------------------------
function renderHeader() {
  const subjectsInUse = new Set(state.games.map(g => g.subject)).size;
  $('#subtitle').textContent = state.games.length
    ? `${plural(state.games.length, 'game')} · Grades 1-12 · ${plural(subjectsInUse, 'subject')}`
    : 'Interactive learning games for grades 1-12';

  const panel = $('#player');
  const p = playerInfo();
  if (!p) { panel.hidden = true; return; }
  panel.hidden = false;
  const ring = $('#ring');
  const fill = $('#ring-fill');
  const C = 2 * Math.PI * 26;
  fill.setAttribute('stroke-dasharray', C.toFixed(2));
  if (p.pct === null) {
    ring.classList.add('is-indeterminate');
    fill.setAttribute('stroke-dashoffset', '0');
  } else {
    ring.classList.remove('is-indeterminate');
    fill.setAttribute('stroke-dashoffset', (C * (1 - p.pct)).toFixed(2));
  }
  $('#level-num').textContent = String(p.level);
  $('#level-label').textContent = `Level ${p.level}`;
  $('#xp-next').textContent = p.xpToNext !== null ? `${fmt(p.xpToNext)} XP to next` : '';
  const bar = $('#xpbar');
  bar.hidden = p.pct === null;
  if (p.pct !== null) { $('#xp-fill').style.width = `${Math.round(p.pct * 100)}%`; bar.setAttribute('aria-valuenow', String(Math.round(p.pct * 100))); }
  $('#xp-text').innerHTML = '';
  $('#xp-text').append(h('strong', {}, fmt(p.xp)), ' XP');
  $('#plays-text').innerHTML = '';
  $('#plays-text').append(h('strong', {}, fmt(p.plays)), p.plays === 1 ? ' play' : ' plays');
}

function thumbNode(game, cls) {
  const subj = subjectOf(game.subject);
  const wrap = h('div', { class: cls });
  wrap.append(h('span', { class: 'la-thumb-initial', 'aria-hidden': 'true' }, (game.title.trim()[0] || subj.short[0] || '?').toUpperCase()));
  const src = thumbUrl(game);
  if (src) {
    const img = h('img', { src, alt: '', loading: 'lazy', decoding: 'async' });
    img.addEventListener('error', () => img.remove(), { once: true });
    wrap.append(img);
  }
  return wrap;
}

function statsLine(id) {
  if (!hasStats()) return null;
  const s = statsFor(id);
  const el = h('span', { class: 'la-stats', dataset: { stats: id } });
  if (!s.plays) { el.textContent = 'Not played yet'; return el; }
  el.append('Best ', h('strong', {}, fmt(s.bestScore)), ` · ${plural(s.plays, 'play')}`);
  return el;
}

function playButton(game, extraClass = '') {
  const btn = h('button', { type: 'button', class: `la-play ${extraClass}`.trim(), 'aria-label': `Play ${game.title}`, dataset: { play: game.id } }, icon('play'), 'Play');
  btn.addEventListener('click', () => openGame(game, btn));
  return btn;
}

function renderContinue() {
  const section = $('#continue');
  const strip = $('#strip');
  const recent = recentGames().slice(0, RECENT_LIMIT);
  if (!recent.length) { section.hidden = true; strip.replaceChildren(); return; }
  section.hidden = false;
  strip.replaceChildren(...recent.map(g => {
    const subj = subjectOf(g.subject);
    const s = statsFor(g.id);
    return h('article', { class: 'la-mini', style: { '--c': subj.color }, dataset: { mini: g.id } },
      thumbNode(g, 'la-mini-thumb'),
      h('div', { class: 'la-mini-body' },
        h('div', { class: 'la-mini-title' }, g.title),
        h('div', { class: 'la-mini-meta' }, `${subj.short} · ${gradeLabel(g)}${s.plays ? ` · Best ${fmt(s.bestScore)}` : ''}`)),
      playButton(g));
  }));
}

function chip({ label, sub, count, color, pressed, disabled, onclick, title }) {
  const el = h('button', {
    type: 'button', class: 'la-chip', 'aria-pressed': pressed ? 'true' : 'false',
    disabled: disabled || undefined, title: title || undefined,
    style: color ? { '--c': color } : undefined,
  },
  color ? h('span', { class: 'la-dot', 'aria-hidden': 'true' }) : null,
  icon('check', 'la-chip-check'),
  label,
  sub ? h('small', {}, sub) : null,
  count !== undefined ? h('span', { class: 'la-chip-count', 'aria-label': `${count} games` }, String(count)) : null);
  el.addEventListener('click', onclick);
  return el;
}

function renderFilters() {
  const f = state.filters;
  const section = $('#filters');
  section.hidden = !state.games.length;
  if (!state.games.length) return;

  const countBy = key => state.games.reduce((m, g) => m.set(g[key], (m.get(g[key]) || 0) + 1), new Map());
  const subjCounts = countBy('subject');
  const bandCounts = countBy('gradeBand');

  const subjectOrder = [...SUBJECTS.map(s => s.id), ...[...state.subjects.keys()].filter(id => !SUBJECTS.some(s => s.id === id))];
  $('#subject-chips').replaceChildren(...subjectOrder.map(id => {
    const s = subjectOf(id);
    const n = subjCounts.get(id) || 0;
    if (!n && !SUBJECTS.some(x => x.id === id)) return null;
    return chip({
      label: s.short, count: n, color: s.color, pressed: f.subjects.has(id), disabled: !n,
      title: n ? s.name : `${s.name}: no games yet`,
      onclick: () => { f.subjects.has(id) ? f.subjects.delete(id) : f.subjects.add(id); renderFilters(); renderGrid(); },
    });
  }).filter(Boolean));

  $('#band-chips').replaceChildren(...BANDS.map(b => chip({
    label: b.label, sub: b.grades, count: bandCounts.get(b.id) || 0, pressed: f.bands.has(b.id), disabled: !bandCounts.get(b.id),
    title: `Grades ${b.grades}`,
    onclick: () => { f.bands.has(b.id) ? f.bands.delete(b.id) : f.bands.add(b.id); renderFilters(); renderGrid(); },
  })));

  const gradeSel = $('#grade');
  if (!gradeSel.options.length) {
    gradeSel.append(h('option', { value: '' }, 'Any grade'));
    for (let g = 1; g <= 12; g++) gradeSel.append(h('option', { value: String(g) }, `Grade ${g}`));
  }
  gradeSel.value = f.grade;

  const mechSel = $('#mechanic');
  const mechanics = [...countBy('mechanic').entries()].sort((a, b) => humanize(a[0]).localeCompare(humanize(b[0])));
  mechSel.replaceChildren(h('option', { value: '' }, 'All mechanics'), ...mechanics.map(([id, n]) => h('option', { value: id }, `${humanize(id)} (${n})`)));
  mechSel.value = mechanics.some(([id]) => id === f.mechanic) ? f.mechanic : '';
  if (!mechSel.value) f.mechanic = '';

  const sortSel = $('#sort');
  if (!sortSel.options.length) sortSel.replaceChildren(...SORTS.map(([v, label]) => h('option', { value: v }, label)));
  sortSel.value = f.sort;

  $('#clear').hidden = !filtersActive();
}

function renderCard(game) {
  const subj = subjectOf(game.subject);
  const band = bandOf(game.gradeBand);
  const card = h('article', { class: 'la-card', style: { '--c': subj.color }, dataset: { game: game.id, subject: game.subject } });
  const thumb = thumbNode(game, 'la-thumb');
  if (game.status && game.status !== 'live' && game.status !== 'released') thumb.prepend(h('span', { class: 'la-badge' }, humanize(game.status)));
  const meta = h('div', { class: 'la-meta' },
    h('span', { class: 'la-pill la-grade' }, gradeLabel(game)),
    band ? h('span', { class: 'la-pill' }, band.label) : null,
    h('span', { class: 'la-pill la-mech' }, humanize(game.mechanic)),
    game.duration ? h('span', { class: 'la-dur' }, icon('clock'), game.duration) : null);
  const stats = statsLine(game.id);
  const foot = h('div', { class: 'la-card-foot' }, stats || h('span', { class: 'la-stats' }), playButton(game));
  card.append(thumb, h('div', { class: 'la-card-body' },
    h('div', { class: 'la-card-subject' }, h('span', { class: 'la-dot', 'aria-hidden': 'true' }), subj.short),
    h('h3', { class: 'la-card-title' }, game.title),
    h('p', { class: 'la-card-tagline', title: game.description || undefined }, game.tagline || game.description),
    meta, foot));
  thumb.addEventListener('click', () => openGame(game, card.querySelector('.la-play')));
  thumb.style.cursor = 'pointer';
  return card;
}

function renderEmpty(kind) {
  const el = $('#empty');
  el.hidden = false;
  if (kind === 'library') {
    el.replaceChildren(h('div', { class: 'la-empty', dataset: { empty: 'library' } },
      icon('empty', 'la-empty-icon'),
      h('h2', {}, 'No games in the library yet'),
      h('p', {}, state.indexError
        ? h('span', {}, 'Could not load ', h('code', {}, state.indexUrl), ` (${state.indexError}).`)
        : h('span', {}, h('code', {}, state.indexUrl), ' is empty.')),
      h('p', {}, 'Generate the index from the game manifests by running ', h('code', {}, 'node tools/build-index.mjs'), ' in the edu-games folder, then reload this page.')));
  } else {
    el.replaceChildren(h('div', { class: 'la-empty', dataset: { empty: 'filters' } },
      icon('search', 'la-empty-icon'),
      h('h2', {}, 'No games match'),
      h('p', {}, 'Try another search term, pick a different grade, or clear the filters.'),
      h('button', { type: 'button', class: 'la-btn la-btn-primary', onclick: clearFilters }, 'Clear filters')));
  }
}

function renderGrid() {
  const grid = $('#grid');
  const empty = $('#empty');
  const count = $('#count');
  grid.setAttribute('aria-busy', 'false');
  if (!state.games.length) { grid.replaceChildren(); count.textContent = ''; renderEmpty('library'); return; }
  const list = visibleGames();
  grid.replaceChildren(...list.map(renderCard));
  count.replaceChildren(h('strong', {}, list.length ? fmt(list.length) : 'No'), list.length === 1 ? ' game' : ' games', filtersActive() ? ' match' : '');
  if (list.length) empty.hidden = true; else renderEmpty('filters');
  $('#clear').hidden = !filtersActive();
}

function renderFooter() {
  const el = $('#footer');
  el.replaceChildren();
  const meta = state.indexMeta;
  if (meta && meta.generatedAt) {
    const d = new Date(meta.generatedAt);
    el.append(`Library index generated ${Number.isNaN(d.getTime()) ? String(meta.generatedAt) : d.toLocaleString()} · `);
  }
  el.append(`${plural(state.games.length, 'game')}`);
  if (state.indexUrl !== DEFAULT_INDEX_URL) el.append(' · index: ', h('code', {}, state.indexUrl));
}

function renderAll() {
  renderHeader();
  renderContinue();
  renderFilters();
  renderGrid();
  renderFooter();
}

// Re-read Progress and update everything that shows stats. Cards are patched in place so focus
// and scroll position survive; the grid is rebuilt only when its order or contents depend on stats.
function refreshStatsUI() {
  refreshStats();
  renderHeader();
  renderContinue();
  const grid = $('#grid');
  const needsRebuild = state.filters.sort === 'best' || (grid.querySelector('.la-card') && !grid.querySelector('[data-stats]'));
  if (needsRebuild) { renderGrid(); return; }
  for (const el of grid.querySelectorAll('[data-stats]')) {
    const fresh = statsLine(el.dataset.stats);
    if (fresh) el.replaceWith(fresh);
  }
}

// ----------------------------------------------------------------------------
// Play modal
// ----------------------------------------------------------------------------
function openGame(game, opener) {
  if (state.modal) closeModal({ restoreFocus: false, refresh: false });
  const subj = subjectOf(game.subject);
  const modal = $('#modal');
  const url = gameUrl(game);
  const frame = h('iframe', { class: 'la-frame', title: game.title, src: url, allow: 'autoplay; fullscreen', loading: 'eager', allowfullscreen: true });
  const openLink = h('a', { class: 'la-btn', href: url, target: '_blank', rel: 'noopener', 'aria-label': 'Open in new tab' }, icon('external'), h('span', { class: 'la-btn-text' }, 'Open in new tab'));
  const closeBtn = h('button', { type: 'button', class: 'la-btn', 'aria-label': 'Close game', dataset: { close: '' } }, icon('close'), h('span', { class: 'la-btn-text' }, 'Close'));
  closeBtn.addEventListener('click', () => closeModal());
  const bar = h('div', { class: 'la-modal-bar' },
    h('div', { class: 'la-modal-title' },
      h('span', { class: 'la-dot', 'aria-hidden': 'true' }),
      h('strong', { id: 'modal-title' }, game.title),
      h('span', { class: 'la-modal-sub' }, `${subj.short} · ${gradeLabel(game)}`)),
    h('div', { class: 'la-modal-actions' }, openLink, closeBtn));
  modal.style.setProperty('--c', subj.color);
  modal.replaceChildren(bar, frame);
  modal.hidden = false;
  document.body.classList.add('la-modal-open');
  state.modal = { game, frame, opener: opener || document.activeElement, focusables: [openLink, closeBtn, frame] };
  closeBtn.focus();
}

function closeModal({ restoreFocus = true, refresh = true } = {}) {
  const m = state.modal;
  if (!m) return;
  state.modal = null;
  try { m.frame.src = 'about:blank'; } catch { /* ignore */ }
  const modal = $('#modal');
  modal.replaceChildren();
  modal.hidden = true;
  document.body.classList.remove('la-modal-open');
  if (refresh) refreshStatsUI();
  if (!restoreFocus) return;
  // The opener may have been re-rendered while the game ran; fall back to the same game's Play button.
  const opener = m.opener;
  let target = opener && document.contains(opener) ? opener : null;
  if (!target && opener && opener.dataset && opener.dataset.play) {
    const id = CSS.escape(opener.dataset.play);
    const scope = opener.closest && opener.closest('#strip') ? '#strip' : '#grid';
    target = document.querySelector(`${scope} [data-play="${id}"]`) || document.querySelector(`[data-play="${id}"]`);
  }
  if (target && isFn(target.focus)) target.focus();
}

function onMessage(e) {
  const d = e.data;
  if (!d || typeof d !== 'object' || d.source !== PLATFORM_SOURCE || typeof d.type !== 'string') return;
  const detail = d.detail && typeof d.detail === 'object' ? d.detail : {};
  const gameId = (typeof detail.gameId === 'string' && detail.gameId) || (state.modal && state.modal.game.id) || null;
  switch (d.type) {
    case 'end':
      noteEnd(gameId, detail);
      notePlayer(detail);
      refreshStatsUI();
      break;
    case 'xp':
    case 'levelup':
      notePlayer(detail);
      refreshStats();
      renderHeader();
      break;
    case 'exit':
      closeModal();
      break;
    default:
      break;
  }
}

function onKeydown(e) {
  const m = state.modal;
  if (m) {
    if (e.key === 'Escape') {
      if (document.activeElement === m.frame) return; // the game owns Escape (pause) while focused
      e.preventDefault();
      closeModal();
      return;
    }
    if (e.key === 'Tab') {
      const items = m.focusables.filter(el => document.contains(el));
      if (!items.length) return;
      const i = items.indexOf(document.activeElement);
      if (e.shiftKey && (i <= 0)) { e.preventDefault(); items[items.length - 1].focus(); }
      else if (!e.shiftKey && (i === items.length - 1 || i === -1 && document.activeElement === document.body)) { e.preventDefault(); items[0].focus(); }
    }
    return;
  }
  if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey) {
    const t = e.target;
    const typing = t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable);
    if (!typing) { e.preventDefault(); $('#search').focus(); }
  }
}

// ----------------------------------------------------------------------------
// Boot
// ----------------------------------------------------------------------------
function bindStatic() {
  let timer = 0;
  $('#search').addEventListener('input', e => {
    clearTimeout(timer);
    const value = e.target.value;
    timer = setTimeout(() => { state.filters.q = value; $('#clear').hidden = !filtersActive(); renderGrid(); }, 120);
  });
  $('#grade').addEventListener('change', e => { state.filters.grade = e.target.value; $('#clear').hidden = !filtersActive(); renderGrid(); });
  $('#mechanic').addEventListener('change', e => { state.filters.mechanic = e.target.value; $('#clear').hidden = !filtersActive(); renderGrid(); });
  $('#sort').addEventListener('change', e => { state.filters.sort = e.target.value; renderGrid(); });
  $('#clear').addEventListener('click', clearFilters);
  window.addEventListener('message', onMessage);
  window.addEventListener('keydown', onKeydown);
  // A game in the iframe (or another tab) writing progress fires 'storage' here; Progress reads
  // storage live, so a debounced refresh keeps stats current even without platform events.
  let storageTimer = 0;
  window.addEventListener('storage', e => {
    if (e.key && !e.key.startsWith('edu-games:')) return;
    clearTimeout(storageTimer);
    storageTimer = setTimeout(refreshStatsUI, 250);
  });
}

async function boot() {
  document.title = LIBRARY_TITLE;
  $('#title').textContent = LIBRARY_TITLE;
  bindStatic();
  const [index, curriculum, progress] = await Promise.all([loadIndex(), loadCurriculum(), loadProgress()]);
  applyCurriculum(curriculum);
  state.progress = progress;
  setGames(index);
  refreshStats();
  renderAll();
}

window.__eduLauncher = { state, openGame, closeModal, refresh: refreshStatsUI, LIBRARY_TITLE };
boot().catch(err => {
  console.error('[launcher] failed to start:', err);
  state.indexError = state.indexError || ((err && err.message) || String(err));
  state.games = [];
  try { renderAll(); } catch { /* ignore */ }
});
